            4, _SIZES, _BUDGETS, prefer="speed"
        )
        steps = [
            profile("merkle", w=mc.plan.config.w, height=mc.plan.config.height).steps
            for mc in frontier
        ]
        self.assertEqual(
            profile(
                "merkle", w=result.plan.config.w, height=result.plan.config.height
            ).steps,
            min(steps),
